export async function listUserMedia(database: Database, ownerId: string) {
  return database
    .select()
    .from(media)
    .where(eq(media.ownerId, ownerId))
    .orderBy(desc(media.createdAt));
}

/** FR-BIZ-03: a business page's photo gallery. */
export async function listBusinessMedia(database: Database, businessId: string) {
  return database
    .select()
    .from(media)
    .where(eq(media.businessId, businessId))
    .orderBy(desc(media.createdAt));
}
